/* From Uiverse.io by mi-series - Tags: material design, minimalist, form, checkbox, password, minimal, #button, password generator */
.__UIV_SCOPE__ .container {
  width: 450px;
  background: #8C92BB;
  border-radius: 8px;
  box-shadow: 0 10px 20px rgba(0,0,0,0.05);
}

.__UIV_SCOPE__ .container p {
  font-weight: 600;
  font-size: 1.31rem;
  padding: 1rem 1.75rem;
  border-bottom: 1px solid #858BB2;
}

.__UIV_SCOPE__ .wrapper {
  margin: 1.25rem 1.75rem;
}

.__UIV_SCOPE__ .wrapper .input-box {
  position: relative;
}

.__UIV_SCOPE__ .input-box input {
  width: 100%;
  height: 53px;
  color: #858BB2;
  background: #858BB2;
  font-size: 1.06rem;
  font-weight: 500;
  border-radius: 4px;
  letter-spacing: 1.4px;
  border: 1px solid #000;
  padding: 0 2.85rem 0 1rem;
}

.__UIV_SCOPE__ .input-box span {
  position: absolute;
  right: 13px;
  cursor: pointer;
  line-height: 53px;
  color: #000;
}

.__UIV_SCOPE__ .input-box span:hover {
  color: #46495E!important;
}

.__UIV_SCOPE__ .wrapper .pass-settings {
  margin: 1.56rem 0 1.25rem;
}

.__UIV_SCOPE__ .pass-settings .options {
  display: flex;
  list-style: none;
  flex-wrap: wrap;
  margin-top: 1rem;
}

.__UIV_SCOPE__ .pass-settings .options .option {
  display: flex;
  align-items: center;
  margin-bottom: 1rem;
  width: calc(100% / 2);
}

.__UIV_SCOPE__ .options .option:first-child input {
  opacity: 0.7;
}

.__UIV_SCOPE__ .options .option input {
  height: 16px;
  width: 16px;
  cursor: pointer;
}

.__UIV_SCOPE__ .options .option label {
  cursor: pointer;
  color: #000;
  padding-left: 0.63rem;
}

.__UIV_SCOPE__ .pass-settings input[type='checkbox'] {
  accent-color: #46496E;
}

.__UIV_SCOPE__ .wrapper .generate-btn {
  width: 100%;
  color: #000;
  border: none;
  outline: none;
  cursor: pointer;
  background: #46496E;
  font-size: 1.06rem;
  padding: 0.94rem 0;
  border-radius: 5px;
  text-transform: uppercase;
  margin: 0.94rem 0 1.3rem;
}

.__UIV_SCOPE__ .wrapper .generate-btn:hover {
  background: #46495E;
}
